class FutestuningCard extends HTMLElement{
 setConfig(c){this.cfg={view:'home',...c};if(!['home','plant','rooms'].includes(this.cfg.view))throw Error('Ismeretlen nézet');if(!this.shadowRoot){this.attachShadow({mode:'open'});this.shadowRoot.innerHTML='<style>'+STYLE+'</style><div id="root"></div><div id="modal"></div>'}this.render()}
 set hass(h){this._hass=h;this.render()} get hass(){return this._hass} s(id){return this._hass?.states?.[id]} on(id){return this.s(id)?.state==='on'}
 num(v){return v!==null&&v!==undefined&&v!==''&&!['unknown','unavailable'].includes(v)&&Number.isFinite(Number(v))?Number(v):null}
 temp(v){const n=this.num(v);return n!==null&&n>-100&&n<150?n.toFixed(1).replace('.',',')+' °C':'—'} fmt(id){return this.temp(this.s(id)?.state)} target(id){return this.temp(this.s(id)?.attributes?.temperature)}
 good(id){const s=this.s(id);return !!s&&!['unknown','unavailable'].includes(s.state)}
 powerLabel(id){const n=this.num(this.s(id)?.state);return n===null?'—':n.toLocaleString('hu-HU')+' W'}
 boilerHeating(){const s=this.s(BOILER.switch)?.state,n=this.num(this.s(BOILER.power)?.state);return s==='off'?false:s==='on'&&n!==null?n>100:null}
 heatState(id){const s=this.s(id);if(!this.good(id))return null;const a=s.attributes?.hvac_action;return a==='heating'?true:['idle','off','cooling','dry','fan'].includes(a)||s.state==='off'?false:null}
 roomClimates(r){return (ROOM_EXTRAS[r[1]]?.climates||[r[3]]).filter(id=>id&&this.good(id))}
 roomHeating(r){const feedback=this.cfg.room_heating_entities?.[r[1]];if(feedback){const st=this.s(feedback)?.state;return st==='on'?true:st==='off'?false:null}if(SHARED_RADIATOR_ROOMS.has(r[1]))return this.pump(2).state;const states=this.roomClimates(r).map(id=>this.heatState(id));if(states.includes(true))return true;if(states.length&&(ROOM_EXTRAS[r[1]]?.climates||[r[3]]).length===states.length&&states.every(x=>x===false))return false;const id=this.cfg.room_heating_entities?.[r[1]],s=this.s(id)?.state;return s==='on'?true:s==='off'?false:null}
 roomCurrent(r){const v=this.num(this.s(r[2])?.state);if(v!==null&&v>-100)return this.temp(v);const ac=ROOM_EXTRAS[r[1]]?.ac;const av=ac?this.num(this.s(ac)?.attributes?.current_temperature):null;if(av!==null&&av>-100&&av<80)return this.temp(av);return this.temp(this.s(this.roomClimates(r)[0])?.attributes?.current_temperature)}
 roomTarget(r){return [...new Set(this.roomClimates(r).map(id=>this.target(id)))].join(' / ')||'—'}
 pump(i){const cfg=this.cfg.pump_feedback_entities?.[i+1];if(cfg){const s=this.s(cfg)?.state;return {state:s==='on'?true:s==='off'?false:null,source:'TECH'}}const s=this.s(DATA.circuits[i][3])?.state,t=this.num(this.s(DATA.buffer)?.state);if(s==='off')return {state:false,source:'Becslés'};if(i===0||s!=='on'||t===null||t<=-100)return {state:null,source:'Becslés'};return {state:i===1?t>30:t>=35,source:'Becslés'}}
 roomStatus(r){const v=this.roomHeating(r);if(SHARED_RADIATOR_ROOMS.has(r[1]))return v===true?'Fűt':v===false?'Nem fűt':'Nincs adat';return v===true?(this.cfg.room_heating_entities?.[r[1]]?'Fűt':'Hőigény'):v===false?'Nem fűt':'Nincs adat'}
 isTrv(id){return this.allowedClimate(id)&&id?.includes('_radiator')&&id?.includes('_sonoff_')}
 canAdjust(id){const s=this.s(id);return this.good(id)&&this.num(s?.attributes?.temperature)!==null&&(!this.isTrv(id)||s.state==='heat')}
 async roomMode(id,mode){if(!this.isTrv(id)||!this.good(id)||!this.s(id).attributes?.hvac_modes?.includes(mode))return;await this.service('climate','set_hvac_mode',{entity_id:id,hvac_mode:mode})}
 diagnostic(){const keys=['friendly_name','current_temperature','temperature','target_temp_high','target_temp_low','hvac_action','hvac_modes','preset_mode','preset_modes','supported_features','min_temp','max_temp','target_temp_step','fan_mode','fan_modes','unit_of_measurement','device_class'];const data={version:VERSION,created_at:new Date().toISOString(),view:this.cfg.view,room_mappings:DATA.rooms,last_command:this.lastCommand||null,entities:Object.fromEntries(Object.entries(this._hass.states).filter(([id])=>id.startsWith('climate.')||id===DATA.buffer||id===DATA.alert||Object.values(BOILER).includes(id)||Object.values(ROOM_EXTRAS).some(x=>x.pump===id)||DATA.circuits.some(c=>c.includes(id))||DATA.rooms.some(r=>r.includes(id))||/^(sensor|binary_sensor|switch|number)\./.test(id)&&/homero|homerseklet|radiator|szivattyu|hoigeny|wifi_rs/.test(id)).map(([id,s])=>[id,{state:s.state,last_updated:s.last_updated,attributes:Object.fromEntries(keys.filter(k=>s.attributes?.[k]!==undefined).map(k=>[k,s.attributes[k]]))}]))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='futestuning-diagnosztika.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
 status(v,words=['Fűt','Nem fűt','Nincs adat']){return v===true?words[0]:v===false?words[1]:words[2]}
 navigate(view){const p={home:'fooldal',plant:'kazanhaz',rooms:'helyisegek'};if(!p[view])return;if(this.cfg.onNavigate){this.cfg.onNavigate(view);return}const base=this.cfg.dashboard_path?.split('/').filter(Boolean).join('/')||location.pathname.split('/').filter(Boolean)[0];history.pushState(null,'','/'+base+'/'+p[view]);window.dispatchEvent(new Event('location-changed'))}
 roomIcon(r){return /fürdő/.test(r[1])?'bath':/garázs/i.test(r[1])?'car':r[1]==='Dolgozó'?'screen':r[1].startsWith('Nappali')?'home':'bed'}
 header(){if(this.cfg.view==='rooms')return `<header class="roomsheader"><div>${ico('fire')}<h1>Helyiségek</h1></div><nav><button class="btn" data-nav="home">Főoldal</button><button class="btn" data-nav="plant">Kazánház</button><span>10 helyiség</span></nav></header>`;const names={home:['Fűtés','Otthon melege, okosan szabályozva'],plant:['Kazánház','Csöves, keverőszelepes rendszerkép'],rooms:['Fűtött helyiségek','Otthoni hőmérséklet-szabályozás']};const [title,sub]=names[this.cfg.view];const date=new Date().toLocaleString('hu-HU',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});const available=DATA.circuits.every(c=>this.good(c[1]))&&this.good(DATA.buffer),alert=this.s(DATA.alert)?.state;return `<header class="mast"><div class="brand">${ico('fire')}<div><h1>${title}</h1><div class="subtitle">${sub}</div><div class="version">Fűtéstuning · ${VERSION}</div></div></div>${this.cfg.view!=='home'?'<button class="btn back" data-nav="home">← Főoldalra</button>':''}<div class="mastinfo indoor">${ico('home')}<div><span class="label">Beltér</span><strong>${this.roomCurrent(DATA.rooms.find(r=>r[1].startsWith('Nappali')))}</strong></div></div><div class="mastinfo date">${ico('calendar')}<div><span class="label">Dátum</span><strong>${date}</strong></div></div><div class="mastinfo">${ico(alert==='on'?'thermo':'check')}<div><span class="label">Rendszer</span><strong class="${alert==='on'?'danger':available?'good':''}">${alert==='on'?'Pufferjelzés':available?'Adatok elérhetők':'Hiányos adatok'}</strong></div></div></header>`}
 zone(i){const c=DATA.circuits[i],s=this.s(c[3])?.state,heat=s==='on'?true:s==='off'?false:null,p=this.pump(i);return `<button class="zone ${heat===true?'hot':''}" data-target="${i}" aria-label="${c[0]} célhőmérséklet"><div class="zonehead"><span class="orb">${ico(['home','fire','rad'][i])}</span><div><h3>${c[0]}${i!==1?' kör':''}</h3><div class="subtitle">${i===1?'Keverőszelepes kör':'Szivattyús kör'}</div></div><span class="chevron">›</span></div><div class="zonevalue">${this.fmt(c[1])}</div><div class="targetline"><span>Célhőmérséklet</span><b>${this.fmt(c[2])}</b></div><div class="statusbar"><strong>${ico(p.state===true?'fire':'power')}${this.status(p.state,['Üzemel','Áll','Ismeretlen'])}</strong><small>${p.source} · ${heat===true?'hőigény aktív':heat===false?'nincs hőigény':'hőigény ismeretlen'}</small></div></button>`}
 summaryBox(icon,label,value,cls=''){return `<div class="summarybox">${ico(icon)}<div><div class="label">${label}</div><strong class="${cls}">${value}</strong></div></div>`}
 home(){const states=DATA.circuits.map(c=>this.s(c[3])?.state),n=states.filter(s=>s==='on').length,missing=states.filter(s=>!['on','off'].includes(s)).length,boiler=this.boilerHeating();return `<div class="homegrid"><section><div class="twocol">${this.zone(0)}${this.zone(1)}</div><div class="threecol">${this.zone(2)}<div class="zone"><div class="zonehead"><span class="orb">${ico('water')}</span><div><h3>HMV</h3><div class="subtitle">Használati melegvíz</div></div></div><div class="zonevalue">— °C</div><div class="targetline"><span>Vízhőmérséklet</span><span>Nincs azonosított szonda</span></div><div class="statusbar"><strong>${ico('power')}${this.status(boiler)}</strong><small>Villanyfűtés · ${this.powerLabel(BOILER.power)}</small></div></div><div class="zone"><div class="zonehead"><span class="orb">${ico('home')}</span><div><h3>Hozzáépítés</h3><div class="subtitle">Külön fűtési terület</div></div></div><div class="zonevalue">2 alkör</div><div class="targetline"><span>Computherm + relé<br>Szülői háló és lenti garázs</span></div><div class="statusbar"><strong>${ico('home')}Külön vezérlés</strong></div></div></div></section><aside class="panel summary"><h2>${ico('chart')} Rendszerösszegzés</h2>${this.summaryBox('tank','Pufferhőmérséklet',this.fmt(DATA.buffer))}${this.summaryBox('fire','Összes hőigény',n+' aktív'+(missing?' · '+missing+' ismeretlen':''),n?'danger':'')}${this.summaryBox('chip','TECH adatok',DATA.circuits.every(c=>this.good(c[1]))?'Elérhetők':'Hiányosak',DATA.circuits.every(c=>this.good(c[1]))?'good':'')}${this.summaryBox('water','HMV állapot',this.status(boiler,['Elektromosan fűt','Nem fűt','Nincs adat']))}${this.summaryBox('thermo','Külső érzékelő','Nincs azonosítva')}</aside></div><section class="panel banner"><div><h2>${ico('pipe')} Kazánházi séma</h2><div class="subtitle">Részletes rendszerkép, szivattyúk, hőfokok</div><div class="navbuttons"><button class="btn primary" data-nav="plant">Megnyitás ›</button><button class="btn" data-nav="rooms">Helyiségek ›</button></div></div>${this.miniSchematic()}</section>`}
 miniSchematic(){return `<svg class="preview" viewBox="0 0 650 170" aria-label="Kazán, puffer és három fűtési kör"><defs><linearGradient id="ft-mini" x2="0" y2="1"><stop stop-color="#d54143"/><stop offset="1" stop-color="#087ad8"/></linearGradient></defs><path d="M100 55H620M620 140H100" fill="none" stroke="#fe694e" stroke-width="7"/><path d="M620 140H100" stroke="#1cb6f6" stroke-width="7"/><rect x="20" y="27" width="95" height="122" rx="10" fill="#152c3d" stroke="#66b5dc"/><text x="67" y="57" text-anchor="middle" fill="#d7f2ff" font-size="15">ATTACK</text><path d="M67 77c25 25 21 46 0 46s-22-21 0-46Z" fill="#fb563d"/><rect x="180" y="12" width="85" height="145" rx="25" fill="url(#ft-mini)" stroke="#92bbd4"/><text x="222" y="75" fill="white" text-anchor="middle" font-size="17">${this.fmt(DATA.buffer)}</text>${[350,450,550].map((x,i)=>`<path d="M${x} 55v85" stroke="#ff7358" stroke-width="6"/><circle cx="${x}" cy="90" r="19" fill="#072c42" stroke="#4ad4f9"/><path d="m${x-10} 96 10-20 10 20Z" fill="#43c4ec"/><text x="${x}" y="165" text-anchor="middle" fill="#abd8f1" font-size="13">${DATA.circuits[i][0]}</text>`).join('')}</svg>`}
 presets(r){const native=this.roomClimates(r).filter(id=>this.isTrv(id)&&!this.s(id).attributes?.preset_modes?.length);if(native.length)return native.map(id=>{const st=this.s(id),a=st.attributes||{},base='sensor.'+id.slice(8);return '<div class="note">'+esc(a.friendly_name||r[1])+' · '+(st.state==='auto'?'Időprogram':st.state==='heat'?'Kézi':st.state==='off'?'Eco / fagyvédelem':esc(st.state))+'</div><div class="presetgrid">'+[['heat','Kézi','home','manual'],['auto','Időprogram','calendar','auto'],['off','Eco / fagyvéd.','leaf','eco']].map(([mode,label,icon,suffix])=>'<button class="preset '+(st.state===mode?'active':'')+'" data-room-mode="'+mode+'" data-climate="'+esc(id)+'" '+(!a.hvac_modes?.includes(mode)?'disabled':'')+'>'+ico(icon)+label+'<div class="tiny">'+this.fmt(base+'_'+suffix+'_target_temperature')+'</div></button>').join('')+'</div>'+(st.state!=='heat'?'<div class="note">A +/− kézi módban állít. Válaszd a Kézi gombot; az Időprogram a meglévő heti programot használja.</div>':'')}).join('');const ids=this.roomClimates(r),single=ids.length===1,st=this.s(ids[0]),supported=st?.attributes?.preset_modes||[],current=st?.attributes?.preset_mode;const items=[['eco','Eco','leaf',['eco']],['comfort','Komfort','home',['comfort','komfort']],['sleep','Éjszaka','moon',['sleep','night']],['away','Távollét','calendar',['away']]];return `<div class="presetgrid">${items.map(([key,label,icon,aliases])=>{const actual=supported.find(x=>aliases.includes(String(x).toLowerCase()));return `<button class="preset ${actual&&current===actual?'active':''}" data-preset="${esc(actual||'')}" data-climate="${esc(ids[0]||'')}" ${!single||!actual?'disabled':''} title="${actual?'Termosztát saját üzemmódja':'A termosztát nem közöl ilyen üzemmódot'}">${ico(icon)}${label}<div class="tiny">${actual?esc(actual):'Nem támogatott'}</div></button>`}).join('')}</div>`}
 acPanel(r){const id=ROOM_EXTRAS[r[1]]?.ac,s=this.s(id),a=s?.attributes||{};if(!s)return `<div class="panel acpanel"><h2>${ico('snow')} Klíma</h2><div class="label">Nincs azonosított klíma ebben a helyiségben.</div></div>`;const modes=a.hvac_modes||[];return `<div class="panel acpanel"><div class="acrow"><h2>${ico('snow')} Klíma</h2><button class="btn" data-ac-toggle="${esc(id)}" ${!this.good(id)||!modes.includes('off')?'disabled':''}>${s.state==='off'?'Bekapcsolás':'Kikapcsolás'}</button></div><div class="label">${esc(s.state)} · cél: ${this.target(id)}</div><div class="accontrols"><select aria-label="Klíma üzemmód" data-ac-mode="${esc(id)}" ${!this.good(id)?'disabled':''}>${modes.map(v=>`<option ${v===s.state?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select>${a.fan_modes?.length?`<select aria-label="Klíma ventilátor" data-ac-fan="${esc(id)}">${a.fan_modes.map(v=>`<option ${v===a.fan_mode?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`:''}<button class="btn" data-step="-1" data-climate="${esc(id)}">−</button><button class="btn" data-step="1" data-climate="${esc(id)}">+</button></div></div>`}
 roomAppearance(r){const v=this.roomHeating(r),physical=SHARED_RADIATOR_ROOMS.has(r[1])||!!this.cfg.room_heating_entities?.[r[1]];return v===null?'unknown':v===false?'idle':physical?'heating':'demand'}
 roomControlIds(r){return ROOM_EXTRAS[r[1]]?.climates||[r[3]].filter(Boolean)}
 canAdjustRoom(r){const ids=this.roomControlIds(r);return ids.length>0&&!this.roomBusy&&ids.every(id=>this.canAdjust(id))}
 async adjustTile(name,delta){const r=DATA.rooms.find(r=>r[1]===name);if(!r||!this.canAdjustRoom(r))return;this.roomBusy=true;this.render();try{for(const id of this.roomControlIds(r)){const ok=await this.adjustRoomTemperature(id,delta);if(ok===false)break}}finally{this.roomBusy=false;this.render()}}
 rooms(){return `<div class="floors-layout">${['Emelet','Földszint','Pince'].map((floor,i)=>`<section class="panel floor"><div class="floorlabel">${ico(i===0?'floor':'home')}<div><h2>${floor}</h2><span class="label">${DATA.rooms.filter(r=>r[0]===floor).length} helyiség</span></div></div><div class="roomgrid">${DATA.rooms.filter(r=>r[0]===floor).map(r=>{const state=this.roomAppearance(r),shared=SHARED_RADIATOR_ROOMS.has(r[1]),estimated=shared&&this.pump(2).source==='Becslés',ids=this.roomControlIds(r),adjust=this.canAdjustRoom(r);return `<article class="zone roomcard ${state}"><button class="room-open" data-room="${esc(r[1])}" aria-label="${esc(r[1])} részletei"><div class="zonehead">${ico(this.roomIcon(r))}<h3>${esc(r[1])}</h3><span class="chevron">›</span></div><div class="roomreadings"><strong class="zonevalue">${this.roomCurrent(r)}</strong><span class="roomtarget"><small>Cél${ids.length>1?' · 2 radiátor':''}</small><b>${this.roomTarget(r)}</b></span></div></button><div class="tilefoot"><span class="roomstate">${this.roomStatus(r)}${estimated?' · becslés':''}</span><span class="tilecontrols">${[-1,1].map(d=>`<button data-tile-step="${d}" data-tile-room="${esc(r[1])}" ${!adjust?'disabled':''} aria-label="${esc(r[1])} célérték ${d<0?'csökkentése':'növelése'}" title="${!ids.length?'Nincs saját termosztát':!adjust?'Minden szelepnek elérhető, kézi módban kell lennie':'Célhőmérséklet állítása'}">${d<0?'−':'+'}</button>`).join('')}</span></div></article>`}).join('')}</div></section>`).join('')}</div><footer class="roomsfooter"><div class="roomlegend"><span class="heating">● Fűt</span><span class="demand">● Hőigény</span><span class="idle">● Nem fűt</span><span class="unknown">● Nincs adat</span></div><span>Fűtéstuning · ${VERSION}</span></footer><div class="room-command error" role="status">${esc(this.error||'')}</div>${this.roomDialogOpen?this.roomDialog():''}`}
 roomDialog(){const selected=DATA.rooms.find(r=>r[1]===this.selectedRoom)||DATA.rooms[0],ids=this.roomClimates(selected),single=ids.length===1,current=this.roomCurrent(selected);return `<div class="room-overlay"><section class="panel room-dialog" role="dialog" aria-modal="true" aria-labelledby="room-dialog-title"><header class="room-dialog-header"><h2 id="room-dialog-title">${esc(selected[1])}</h2><button class="btn" data-close-room aria-label="Részletes ablak bezárása">✕</button></header><div class="room-dialog-body"><div class="room-thermostat"><div class="detailhead"><span class="orb">${ico(this.roomIcon(selected))}</span><div><h2>${selected[1]}</h2><div class="label">${selected[0]} · ${this.roomStatus(selected)}</div></div></div><div class="dialwrap"><svg class="dialsvg" viewBox="0 0 360 310"><defs><linearGradient id="dialgradient"><stop stop-color="#078cff"/><stop offset=".6" stop-color="#28c4ff"/><stop offset="1" stop-color="#f15654"/></linearGradient></defs><path d="M67 265A145 145 0 1 1 293 265" fill="none" stroke="#153d59" stroke-width="16"/><path d="M67 265A145 145 0 1 1 293 265" fill="none" stroke="url(#dialgradient)" stroke-width="10"/><path d="M57 275A159 159 0 1 1 303 275" fill="none" stroke="#39bfff" stroke-width="10" stroke-dasharray="1 7" opacity=".5"/><circle cx="180" cy="20" r="10" fill="#fff" stroke="#21cfff" stroke-width="3"/></svg><div class="dialtext"><span class="label">Jelenlegi hőmérséklet</span><strong class="current">${current}</strong><hr><span class="label">Beállított hőmérséklet</span><strong class="setpoint">${this.roomTarget(selected)}</strong></div><button class="round minus" data-step="-1" data-climate="${esc(ids[0]||'')}" ${!single||!this.canAdjust(ids[0])?'disabled':''} aria-label="Célhőmérséklet csökkentése">−</button><button class="round plus" data-step="1" data-climate="${esc(ids[0]||'')}" ${!single||!this.canAdjust(ids[0])?'disabled':''} aria-label="Célhőmérséklet növelése">+</button></div>${(ROOM_EXTRAS[selected[1]]?.climates?.length||0)>ids.length?`<div class="error">${ids.length}/${ROOM_EXTRAS[selected[1]].climates.length} szelep elérhető. A többi szelep állapota ismeretlen.</div>`:""}${ids.length>1?`<div class="note">Külön szelepek: ${ids.map(id=>`<div class="inforow"><span>${esc(this.s(id)?.attributes?.friendly_name||id)}</span><span><button class="btn" data-step="-1" data-climate="${esc(id)}" ${!this.canAdjust(id)?"disabled":""}>−</button> ${this.target(id)} <button class="btn" data-step="1" data-climate="${esc(id)}" ${!this.canAdjust(id)?"disabled":""}>+</button></span></div>`).join('')}</div>`:''}${this.presets(selected)}</div><div class="room-more">${this.acPanel(selected)}<div class="panel acpanel"><h2>További információk</h2><div class="inforow"><span>Helyiséghőmérséklet</span><b>${current}</b></div><div class="inforow"><span>Beállított hőmérséklet</span><b>${this.roomTarget(selected)}</b></div><div class="inforow"><span>Fűtési állapot</span><b>${this.roomStatus(selected)}</b></div><div class="note">${SHARED_RADIATOR_ROOMS.has(selected[1])?'Közös radiátorkör. TECH-visszajelzés esetén annak állapota érvényes; enélkül becslés: radiátoros MINI-D hőigény és legalább 35 °C-os puffer.':'A termosztát közölt hőigénye, nem igazolt hőleadás.'}</div></div><div class="error" role="status">${esc(this.error||'')}</div><div class="note" role="status">${esc(this.commandMessage||'')}</div><button class="btn" data-diagnostic>Diagnosztika letöltése</button></div></div><footer class="room-dialog-footer"><button class="btn" data-close-room>Vissza a helyiségekhez</button></footer></section></div>`}
 closeRoom(){this.roomDialogOpen=false;this.render();[...this.shadowRoot.querySelectorAll('[data-room]')].find(b=>b.dataset.room===this.selectedRoom)?.focus()}

 plant(){return `<div class="plant-top"><div class="panel"><h2>${ico('pipe')} Hőforrás oldal</h2><div class="metricrow"><span>ATTACK · PROFI PID</span><b>Önálló vezérlés</b></div><div class="metricrow"><span>Puffer · TH Elite</span><b class="plantreading">${this.fmt(DATA.buffer)}</b></div><div class="note">Egyetlen mért pont. Nincs háromzónás mérés.</div></div><div class="panel"><h2>${ico('chip')} TECH vezérlés – fő rendszer</h2>${DATA.circuits.map((c,i)=>`<div class="inforow"><span>0${i+1} ${c[0]}</span><b>${this.fmt(c[1])} · cél ${this.fmt(c[2])}</b></div>`).join('')}</div><div class="panel"><h2>${ico('water')} HMV</h2><div class="metricrow"><span>Vízhőmérséklet</span><b>— °C</b></div><div class="note">Nincs azonosított szonda</div><div class="inforow"><span>Elektromos fűtés</span><b>${this.status(this.boilerHeating())}</b></div><div class="label">${this.powerLabel(BOILER.power)}</div></div></div><div class="diagram">${this.schematic()}</div><div class="plant-bottom"><div class="panel"><h2>Működési logika</h2><p>A szivattyúkat a TECH vezérli.</p><p>Pince/radiátor: csak szivattyú. Padló: keverős kör.</p><p>A rajzon csak a narancs TECH célértékek állíthatók.</p></div><div class="panel"><h2>Jelmagyarázat</h2><p>Piros: előremenő · kék: visszatérő · nyilak: irány</p><p>Forgás: TECH-visszajelzés vagy jelzett becslés.</p><p>Becslés: MINI-D + puffer &gt;30 °C padló / ≥35 °C radiátor.</p></div><div class="panel"><h2>Szivattyúk állapota</h2>${DATA.circuits.map((c,i)=>{const p=this.pump(i);return `<div class="inforow"><span>P${i+1} · ${c[0]}</span><b class="${p.state===true?'good':''}">${this.status(p.state,['Üzemel','Áll','Ismeretlen'])} · ${p.source}</b></div>`}).join('')}</div></div>`}
 schematic(){const pump=(x,y,i)=>{const p=this.pump(i),col=p.state===true?'#3df3a2':p.state===false?'#8cb0c6':'#58768a';return `<g transform="translate(${x} ${y})"><circle r="22" fill="#07283c" stroke="${col}" stroke-width="3"/><g class="${p.state===true?'pump-spin':''}" style="transform-origin:0px 0px">${[0,120,240].map(a=>`<path d="M0 0Q-6-21 10-13Q20-8 0 0" transform="rotate(${a})" fill="${col}"/>`).join('')}</g></g>`};const hot='#ff745b',cold='#24baff';return `<svg class="plant-svg" viewBox="0 0 1500 620" role="img" aria-label="Kazán, puffer, három TECH kör, HMV és külön hozzáépítés"><defs><linearGradient id="tank" x2="0" y2="1"><stop stop-color="#f5524b"/><stop offset=".5" stop-color="#8a306c"/><stop offset="1" stop-color="#0483e2"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="3"/></filter></defs><path d="M185 150H230M390 150H1450" stroke="${hot}" stroke-width="12" fill="none"/><path d="M1450 530H390V430M230 430H185" stroke="${cold}" stroke-width="12" fill="none"/><text x="430" y="124" fill="#ffb3a4" font-size="18">Előremenő →</text><text x="430" y="564" fill="#8bdbff" font-size="18">← Visszatérő</text><rect x="35" y="195" width="150" height="245" rx="15" fill="#112f44" stroke="#7994aa" stroke-width="3"/><path d="M35 210 53 192H167L185 210" fill="#bd3540" stroke="#f55c5e"/><rect x="50" y="220" width="120" height="180" rx="8" fill="#071c2b" stroke="#ee5c50"/><text x="110" y="375" text-anchor="middle" fill="white" font-size="20">Kazán · ATTACK</text><path d="M106 261c-42 47-26 69 0 69s45-22 0-69Z" fill="#fa573f"/><path d="M110 195V150H230" fill="none" stroke="${hot}" stroke-width="12"/><path d="M185 430H230" fill="none" stroke="${cold}" stroke-width="12"/><rect x="230" y="45" width="160" height="435" rx="53" fill="url(#tank)" stroke="#9fc9df" stroke-width="3"/><ellipse cx="310" cy="64" rx="72" ry="15" fill="#162d3e" stroke="#8cb7cc"/><text x="310" y="120" text-anchor="middle" fill="white" font-size="25" font-weight="800">Puffer</text><text x="310" y="222" text-anchor="middle" fill="white" font-size="32" font-weight="800">${this.fmt(DATA.buffer)}</text><text x="310" y="253" text-anchor="middle" fill="#dfedff" font-size="18">TH Elite</text><text x="310" y="399" text-anchor="middle" fill="white" font-size="16">1 mért pont</text>${[480,675,870].map((x,i)=>{const c=DATA.circuits[i],p=this.pump(i);return `<g><path d="M${x} 150V442" fill="none" stroke="${hot}" stroke-width="9"/><path d="M${x+70} 445V530" fill="none" stroke="${cold}" stroke-width="9"/><path d="M${x+70} 442V530" stroke="${cold}" stroke-width="9"/><rect x="${x-68}" y="185" width="165" height="124" rx="12" fill="#06233a" stroke="#179bc9"/><text x="${x+14}" y="214" text-anchor="middle" fill="white" font-size="18">0${i+1} ${c[0]}</text><text x="${x+14}" y="249" text-anchor="middle" fill="white" font-size="27" font-weight="750">${this.fmt(c[1])}</text><g role="button" tabindex="0" data-target="${i}" aria-label="${c[0]} célhőmérséklet" style="cursor:pointer"><rect x="${x-61}" y="263" width="151" height="36" rx="7" fill="#633b26" stroke="#ffc080"/><text x="${x+14}" y="287" text-anchor="middle" fill="#ffdbac" font-size="17">Cél: ${this.fmt(c[2])} ›</text></g>${i===1?`<path d="M${x+70} 442V340H${x+18}" fill="none" stroke="${cold}" stroke-width="6"/>`:''}${pump(x,375,i)}${i===1?`<path d="m${x-18} 326 36 0-36 28 36 0Z" fill="#a9c6d8" stroke="#fff"/><rect x="${x-11}" y="310" width="22" height="20" fill="#15344d" stroke="#edb35e"/><text x="${x}" y="326" text-anchor="middle" fill="#ffd284" font-size="14">M</text>`:''}<rect x="${x-23}" y="421" width="96" height="45" rx="5" fill="#0a2132" stroke="#b3d7e8"/>${[0,1,2,3,4].map(k=>`<path d="M${x-13+k*17} 426v35" stroke="#a7d9f0" stroke-width="6"/>`).join('')}<text x="${x+13}" y="495" text-anchor="middle" fill="${p.state===true?'#46efb3':'#a2c5db'}" font-size="13">${p.source} · ${this.status(p.state,['Üzemel','Áll','Ismeretlen'])}</text></g>`}).join('')}<path d="M1045 150V350M1100 470V530" fill="none" stroke="${hot}" stroke-width="9"/><path d="M1100 470V530" stroke="${cold}" stroke-width="9"/><rect x="985" y="185" width="150" height="105" rx="10" fill="#06233a" stroke="#179bc9"/><text x="1060" y="219" text-anchor="middle" fill="white" font-size="20">04 HMV</text><text x="1060" y="250" text-anchor="middle" fill="white" font-size="25">— °C</text><text x="1060" y="274" text-anchor="middle" fill="#a4cbe2" font-size="15">nincs szonda</text><rect x="1020" y="350" width="80" height="135" rx="25" fill="#254e69" stroke="#a9cbdf"/><path d="M1040 371h40v20h-40v20h40v20h-40v20h40" fill="none" stroke="#d9eefb" stroke-width="5"/><rect x="1170" y="180" width="295" height="322" rx="12" fill="#042037" stroke="#18a0cc" stroke-dasharray="5 4"/><text x="1317" y="209" text-anchor="middle" fill="#69dfff" font-size="19">05 Hozzáépítés · külön körök</text><path d="M1180 150V335H1240M1275 430V530" stroke="${hot}" stroke-width="8" fill="none"/><path d="M1275 430V530" stroke="${cold}" stroke-width="8"/><rect x="1240" y="285" width="53" height="160" rx="20" fill="#254d67" stroke="#b1d7ed"/><text x="1355" y="285" fill="white" text-anchor="middle" font-size="17">Garázs · radiátor</text><text x="1355" y="368" fill="white" text-anchor="middle" font-size="17">Háló · padló/fal</text><path d="M1293 316h140M1293 400h140" stroke="${hot}" stroke-width="7"/><text x="1320" y="468" fill="#a1c8dd" text-anchor="middle" font-size="14">Computherm · nincs visszajelzés</text>${[470,680,890,1060,1235,1400].map(x=>`<path d="m${x} 143 11 7-11 7" fill="none" stroke="#fff" stroke-width="3"/><path d="m${x} 523-11 7 11 7" fill="none" stroke="#fff" stroke-width="3"/>`).join('')}<text x="40" y="604" fill="#96c0dc" font-size="15">Irányjelzés és sematikus csövezés. A forgásjelzés a felirat szerinti visszajelzés vagy becslés; nem áramlásmérés.</text></svg>`}
 async service(domain,service,data){if(domain!=='climate'||!['set_temperature','set_preset_mode','set_hvac_mode','set_fan_mode'].includes(service)||!this.allowedClimate(data.entity_id))return false;try{await this._hass.callService(domain,service,data);this.error='';this.lastCommand={domain,service,entity_id:data.entity_id,data,result:'accepted',at:new Date().toISOString()};this.commandMessage='A Home Assistant fogadta a parancsot; az eszköz visszajelzése még ellenőrizendő.';this.render();return true}catch(e){this.error='A parancs nem sikerült: '+String(e?.message||e?.code||'ismeretlen hiba');this.lastCommand={domain,service,entity_id:data.entity_id,result:'error',error:this.error,at:new Date().toISOString()};this.render();return false}}
 allowedClimate(id){return DATA.rooms.some(r=>r[3]===id)||Object.values(ROOM_EXTRAS).some(x=>x.ac===id||x.climates?.includes(id))}
 async adjustRoomTemperature(id,delta){if(this.isTrv(id)&&this.s(id)?.state!=='heat'){this.error='Kézi állításhoz előbb válaszd a Kézi módot.';this.render();return}if(!this.allowedClimate(id)||!this.good(id)){this.error='A hozzárendelt termosztát nem elérhető.';this.render();return}const a=this.s(id).attributes||{},v=this.num(a.temperature);if(v===null){this.error='A termosztát nem közöl állítható célhőmérsékletet.';this.render();return}const min=this.num(a.min_temp)??5,max=this.num(a.max_temp)??35,step=this.num(a.target_temp_step)||.5,next=Math.max(min,Math.min(max,Math.round((v+delta*step)*100)/100));if(next!==v)return await this.service('climate','set_temperature',{entity_id:id,temperature:next});return true}
 async preset(id,value){if(!this.allowedClimate(id)||!this.good(id)||!this.s(id).attributes?.preset_modes?.includes(value))return;await this.service('climate','set_preset_mode',{entity_id:id,preset_mode:value})}
 async acMode(id,value){if(!Object.values(ROOM_EXTRAS).some(x=>x.ac===id)||!this.good(id)||!this.s(id).attributes?.hvac_modes?.includes(value))return;await this.service('climate','set_hvac_mode',{entity_id:id,hvac_mode:value})}
 async acFan(id,value){if(!Object.values(ROOM_EXTRAS).some(x=>x.ac===id)||!this.good(id)||!this.s(id).attributes?.fan_modes?.includes(value))return;await this.service('climate','set_fan_mode',{entity_id:id,fan_mode:value})}
 render(){if(!this.shadowRoot||!this._hass)return;const active=this.shadowRoot.activeElement,focusData=active?{label:active.getAttribute('aria-label'),data:{...active.dataset}}:null,scrollTop=this.shadowRoot.querySelector('.room-dialog-body')?.scrollTop||0;const r=this.shadowRoot.getElementById('root');r.innerHTML=`<main class="root view-${this.cfg.view}">${this.header()}${this.cfg.view==='home'?this.home():this.cfg.view==='plant'?this.plant():this.rooms()}</main>`;if(this.roomDialogOpen){r.querySelectorAll('.roomsheader,.floors-layout,.roomsfooter').forEach(e=>e.inert=true);const body=r.querySelector('.room-dialog-body');if(body)body.scrollTop=scrollTop}if(focusData){const focus=[...r.querySelectorAll('button,select')].find(e=>e.getAttribute('aria-label')===focusData.label&&JSON.stringify({...e.dataset})===JSON.stringify(focusData.data));focus?.focus({preventScroll:true})}r.querySelectorAll('[data-diagnostic]').forEach(e=>e.onclick=()=>this.diagnostic());r.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>this.navigate(e.dataset.nav));r.querySelectorAll('[data-room]').forEach(e=>e.onclick=()=>{this.selectedRoom=e.dataset.room;this.roomDialogOpen=true;this.render();this.shadowRoot.querySelector('[data-close-room]')?.focus()});r.querySelectorAll('[data-tile-step]').forEach(e=>e.onclick=()=>this.adjustTile(e.dataset.tileRoom,Number(e.dataset.tileStep)));r.querySelectorAll('[data-close-room]').forEach(e=>e.onclick=()=>this.closeRoom());const overlay=r.querySelector('.room-overlay');if(overlay){overlay.onclick=e=>{if(e.target===overlay)this.closeRoom()};overlay.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();this.closeRoom()}if(e.key==='Tab'){const buttons=[...overlay.querySelectorAll('button:not(:disabled),select:not(:disabled)')].filter(x=>x.getClientRects().length),first=buttons[0],last=buttons[buttons.length-1],focus=this.shadowRoot.activeElement;if(e.shiftKey&&focus===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&focus===last){e.preventDefault();first.focus()}}}}r.querySelectorAll('[data-target]').forEach(e=>{e.onclick=()=>this.editTarget(Number(e.dataset.target));e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();this.editTarget(Number(e.dataset.target))}}});r.querySelectorAll('[data-step]').forEach(e=>e.onclick=()=>this.adjustRoomTemperature(e.dataset.climate,Number(e.dataset.step)));r.querySelectorAll('[data-room-mode]').forEach(e=>e.onclick=()=>this.roomMode(e.dataset.climate,e.dataset.roomMode));r.querySelectorAll('[data-preset]').forEach(e=>e.onclick=()=>this.preset(e.dataset.climate,e.dataset.preset));r.querySelectorAll('[data-ac-mode]').forEach(e=>e.onchange=()=>this.acMode(e.dataset.acMode,e.value));r.querySelectorAll('[data-ac-fan]').forEach(e=>e.onchange=()=>this.acFan(e.dataset.acFan,e.value));r.querySelectorAll('[data-ac-toggle]').forEach(e=>e.onclick=()=>{const id=e.dataset.acToggle,s=this.s(id);this.acMode(id,s.state==='off'?(s.attributes.hvac_modes.includes('heat')?'heat':s.attributes.hvac_modes.find(x=>x!=='off')):'off')})}
 editTarget(i){const c=DATA.circuits[i],s=this.s(c?.[2]);if(!s||!this.good(c[2]))return;let v=this.num(s.state);if(v===null)return;const min=this.num(s.attributes?.min)??10,max=this.num(s.attributes?.max)??80,step=this.num(s.attributes?.step)||1;const holder=this.shadowRoot.getElementById('modal');holder.innerHTML=`<div class="overlay"><section class="panel modal"><div class="acrow"><h2>${c[0]} · TECH célérték</h2><button class="btn" id="close">Bezárás</button></div><div class="stepper"><button class="btn" id="minus">−</button><strong id="temp"></strong><button class="btn" id="plus">+</button></div><button class="btn primary" id="save">Mentés</button><div id="msg" role="status" class="error"></div></section></div>`;const show=()=>holder.querySelector('#temp').textContent=this.temp(v);show();holder.querySelector('#close').onclick=()=>holder.innerHTML='';holder.querySelector('#minus').onclick=()=>{v=Math.max(min,Math.round((v-step)*100)/100);show()};holder.querySelector('#plus').onclick=()=>{v=Math.min(max,Math.round((v+step)*100)/100);show()};holder.querySelector('#save').onclick=async()=>{const b=holder.querySelector('#save');b.disabled=true;try{await this._hass.callService('number','set_value',{entity_id:c[2],value:v});holder.innerHTML=''}catch(e){b.disabled=false;holder.querySelector('#msg').textContent='Mentés sikertelen. Próbáld újra.'}}}
 getCardSize(){return 12}
}
if(!customElements.get('futestuning-card'))customElements.define('futestuning-card',FutestuningCard);
window.customCards=window.customCards||[];window.customCards.push({type:'futestuning-card',name:'Fűtéstuning',description:'Főoldal · Kazánház · Helyiségek'});

